package mapper;import entity.ChiTietNhapKho;import java.sql.ResultSet;import java.sql.SQLException;public class ChiTietNhapKhoMapper implements RowMapper<ChiTietNhapKho> {    @Override    public ChiTietNhapKho mapper(ResultSet rs) {        try {            String maChiTiet = rs.getString("maChiTiet");            String maPhieuNhap = rs.getString("maPhieuNhap");            String maSanPham = rs.getString("maSanPham");            int soLuong = rs.getInt("soLuong");            long donGia = rs.getLong("donGia");            long thanhTien = rs.getLong("thanhTien");            return new ChiTietNhapKho(maChiTiet, maPhieuNhap, maSanPham, soLuong, donGia, thanhTien);        } catch (SQLException e) {            return null;        }    }}